        "Formos: du hältst, er hält (a → ä), hielt, hat gehalten. Laikyti kuo nors, vertinti: jemanden/etwas für + Akkusativ halten.",
        "Halt! kaip komanda reiškia „stok!“, o Halt die Tür! – „Palaikyk duris!“."
